ON CONFLICT (student_id) DO UPDATE SET
  first_name = EXCLUDED.first_name,
  middle_name = COALESCE(EXCLUDED.middle_name, public.alumni_eligible.middle_name),
  last_name = EXCLUDED.last_name,
  program = EXCLUDED.program,
  year_graduated = GREATEST(public.alumni_eligible.year_graduated, EXCLUDED.year_graduated),
  graduation_date = EXCLUDED.graduation_date
WHERE public.alumni_eligible.user_id IS NULL;


-- Step 3: Verification queries
SELECT program, year_graduated, COUNT(*) as unclaimed_count
FROM public.alumni_eligible
WHERE user_id IS NULL
GROUP BY program, year_graduated
ORDER BY year_graduated DESC, program ASC;

